---GetGoodsVoById
---@param refId number
---@param idAreaType Constants.IDArea
---@return GoodsVo
function GoodsConfMgr:GetGoodsVoById(refId, idAreaType)
    if isNull(idAreaType) then
        idAreaType = Constants.IDArea.Goods
    end

    local autoId = nil
    local voName = "GoodsVo"
    local idType = GoodsUtils.GetIdType(refId, idAreaType)
    local define = GoodsTypeDefines[idType]
    if define then
        autoId = define.id
        voName = define.vo or voName
    -- elseif idType == Constants.IDType.GoodsCommission then
    --     --转一层
    --     ---@type GoodsCommissionVo
    --     local vo = CfUtils.GetCfVo(AutoIds.IdSetting2600, "GoodsCommissionVo", refId)
    --     if vo then
    --         return self:GetGoodsVoById(vo.effectId)
    --     end
    end
    if autoId then
        ---@type SettingMgr
        local settingMgr = SettingMgr:GetInstance()
        local setting = settingMgr:GetSetting(autoId, voName)
        return setting:Get(refId)
    end

end

---GetPhotoPathSpecialById
---一种特殊的道具路径
---@param refId number
function GoodsConfMgr:GetPhotoPathSpecialById(refId)
    local goodsVo = self:GetGoodsVoById(refId)
    if goodsVo then
        --有特殊的图片就取这个
        if not string.isEmpty(goodsVo.photoIdSmall) then
            return goodsVo.photoIdSmall
        else
            return goodsVo.photoPath
        end
    end
    return nil
end

---GetPhotoPathById
---返回道具路径
---@param refId number
---@return string
function GoodsConfMgr:GetPhotoPathById(refId)
    local goodsVo = self:GetGoodsVoById(refId)
    if goodsVo then
        return goodsVo.photoPath
    end
end

---返回道具名称
---@param refId number
---@return string
function GoodsConfMgr:GetGoodsNameById(refId)
    local goodsVo = self:GetGoodsVoById(refId)
    if goodsVo then
        return tostring(goodsVo.name)
    end
    return tostring(refId)
end

---GetExpGoodsVoList
---获得经验道具vo列表
function GoodsConfMgr:GetExpGoodsVoList(goodsEffectType)
    ---@type SettingMgr
    local settingMgr = SettingMgr:GetInstance()
    ---@type table<string, TableML.TableFileRow>
    local tableFile = settingMgr:Get(AutoIds.IdSetting21)
    local GoodsVo = import('Game.Setting.Vo.GoodsVo')
    local goodsVoList = {}
    goodsEffectType = goodsEffectType or Constants.GoodsEffectType.ExpGoods
    for i, row in pairs(tableFile) do
        local effectType = parse_number(row, "effectType")
        if checkNumber(effectType) == goodsEffectType then
            local vo = GoodsVo.New()
            vo:FillVo(row)
            table.insert(goodsVoList, vo)
        end
    end
    return goodsVoList
end

---GetGiftRewards
---获取礼包内的奖励
function GoodsConfMgr:GetGiftRewards(goodsId)
    goodsId = checkNumber(goodsId)
    local type = GoodsUtils.GetIdType(goodsId)
    --不是宝箱类型
    if not type == Constants.IDType.GoodsGift then
        return {}
    end
    local vo = self:GetGoodsVoById(goodsId)
    if not vo then
        return {}
    end

    local _t = {}
    if checkNumber(vo.effectId) > 0 then
        local t = CfUtils.GetIdGroupData(AutoIds.IdSetting1030, vo.effectId)
        if t then
            for _, _rewardId in pairs(t) do
                table.insert(_t, {
                    goodsId = checkNumber(_rewardId),
                    num = nil
                })
            end
        end
    end
    return _t
end

