---CheckIsCanJump
---检查是否能跳转
---@param row TableML.TableFileRow
function GoodsConfMgr:CheckIsCanJump(row, isShowTips, extraPara)
    local isShowTips = isNull(isShowTips) or false
    local functionID = checkInt(row:Get("functionID"))
    local moduleID = checkInt(row:Get("moduleID"))
    local jumpID = checkInt(row:Get("ID"))
    --先判断功能有没有解锁
    --优化gc 600B --> 0B
    local isUnlock, str = SystemToggleMgr:GetInstance():IsUnLockModel(functionID, not isShowTips)
    if (not isUnlock) and isShowTips then
        GameUtils.Toast(checkString(str))
    end
    if not isUnlock then
        return false
    end
    --区域部分特殊
    if functionID == Constants.SystemToggleIds.Id2001 then
        local t = checkTable(CfUtils.Split(checkString(row:Get("parameter"))))
        local regionId = checkNumber(t[1])
        if regionId > 0 then
            local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
            isUnlock, str = ActionUtils.IsUnlockRegionalSecondPoint(regionId)
        end
    elseif functionID == Constants.SystemToggleIds.Id2003 then
        local AnnihilationUtils = import('Game.UI.FightReady.UIMainChapter.AnnihilationUtils')
        local bossTypeId = checkNumber((row:Get("parameter")))
        bossTypeId = bossTypeId == 0 and 1 or bossTypeId
        isUnlock, str = AnnihilationUtils.CheckAnnihilationBossUnlocked(0, 0, bossTypeId)
    elseif moduleID == Constants.UITypeIds.UIActionCityStoreDialog then
        local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
        local id = checkNumber((row:Get("parameter")))
        isUnlock, str = ActionUtils.IsUnlockStore(id)
    elseif moduleID == Constants.UITypeIds.UIOverseaTowerEntryDialog then
        local OverseaTowerUtils = import('Game.UI.FightReady.OverseaTower.OverseaTowerUtils')
        --优化gc 200B --> 141B
        isUnlock, str = OverseaTowerUtils.IsFunctionUnlock(jumpID, not isShowTips)
    elseif moduleID == Constants.UITypeIds.UIActivityJapanesePokerEntryDialog then
        ---@type ActivityConstants
        local ActivityConstants = import("Game.Activity.ActivityConstants")
        if checkInt(extraPara[1]) == ActivityConstants.ActivityType.JapaneseStory then
            local JapaneseStoryMgr = import("Game.Activity.JapaneseStory.JapaneseStoryMgr"):GetInstance()
            local JapaneseStoryConstants = import('Game.Activity.JapaneseStory.JapaneseStoryConstants')
            if not JapaneseStoryMgr:CheckEntryBtnUnlock(JapaneseStoryConstants.EntryBtnType.CARD) then
                local conf = JapaneseStoryMgr:GetEntryBtnConf(JapaneseStoryConstants.EntryBtnType.CARD)
                local questVo = QuestConfMgr:GetInstance():GetQuestVoById(conf.unlockLevel)
                isUnlock = false
                str = localize("请先通关前置关卡_name_",{_name_ = questVo.name})
            end
        end
    end
    if (not isUnlock) and isShowTips then
        GameUtils.Toast(checkString(str))
    end
    if not isUnlock then
        return false
    end
    --[[    local curScene = SceneManagement:GetInstance():Current()
        if curScene then
            local id = KCookie.Get(Constants.UICacheDataKeys.MainSceneID)
            if not isNull(id) then
                if checkNumber(id) ~= checkNumber(curScene.identifier) then
                    if isShowTips then
                        GameUtils.Toast(localize("该场景不能跳转"))
                    end
                    return false
                end
            end
        end]]
    return true
end

---在有些模块中不显示金币前往营业报表
---@param moduleId number 要跳转的ID
function GoodsConfMgr:IsNotShowBlackModule(moduleId)
    ---如果要去的是营业报表 这时候要屏蔽掉一些界面 不能去
    local moduleId = checkNumber(moduleId)
    if moduleId == Constants.UITypeIds.UIMaidCoffeeStatementDialog then
        local lastDialog = CS.Engine.UI.UIModule.CurrentScreen:LastDialog()
        if not isNull(lastDialog) then
            local moduleId = CS.Engine.UI.UIModule.CurrentScreen:LastDialog().Argument.id
            if NotShowGoldJumpModule[moduleId] then
                return true
            end
        end
    end
    return false
end

---ExecuteJump
---执行跳转的逻辑
---@param row TableML.TableFileRow 功能切割表 行数据
---@param goodsVo GoodsVo 道具对象
---@param position number 跳转的列表第几项数据
---@param isHomeJump boolean 是否是主菜单按钮功能中的跳转
---@param extraPara table 额外得一些参数 数组传进来 暂时主线用
function GoodsConfMgr:ExecuteJump(row, goodsVo, position, isHomeJump, extraPara)
    Events.Broadcast(Constants.EventNames.EXECUTE_JUMP)
    ---先关闭跳转的tips
    local tipsBoard = CS.UnityEngine.GameObject.Find("CommonTipsBoardGoods")
    if not isNull(tipsBoard) then
        KTool.SafeDelete(tipsBoard)
    end

    if not self:CheckIsCanJump(row, nil, extraPara) then
        return
    end

    local secondConfirm = UIModule.RootCanvas.transform:Find("SecondConfirmPopUp")
    if not isNull(secondConfirm) then
        KTool.SetActive(secondConfirm.gameObject, false)
        KTool.SafeDelete(secondConfirm.gameObject)
    end
    ---如果是主菜单的跳转时不入暂 isStack = false
    local isStack = (not checkBool(isHomeJump))

    ---实际的界面id
    local moduleId = checkInt(row:Get("moduleID"))
    local parameter = checkString(row:Get("parameter"))
    local jumpType = checkInt(row:Get("jumpType"))
    local functionID = checkInt(row:Get("functionID"))
    local jumpID = checkInt(row:Get("ID"))
    -- print("[跳转]", moduleId, parameter, jumpType)
    -- 处理活动社区跳转
    if moduleId == 998 then
        GameUtils.OpenCommunity(checkTable(extraPara).url)
        return
    elseif moduleId == Constants.UITypeIds.OpenGridActivityTask then
        UIModule.OpenDialog({ id = Constants.UITypeIds.OpenGridActivityTask})
        return
    elseif moduleId == Constants.UITypeIds.UIHPDialog then
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIHPDialog, parameters = { overrideSorting = 0, hideBtnMore = true } })
        return
    elseif moduleId == Constants.UITypeIds.InvestPopup then
        UIModule.OpenDialog({ id = Constants.UITypeIds.InvestPopup})
        return
    elseif moduleId == Constants.UITypeIds.UIActivityEntryWelfareDialog then
        local t = {}
        local dialogs = UIModule.CurrentScreen.dialogs
        for _, dialog in pairs(dialogs) do
            if checkNumber(dialog.Argument.id) ~= Constants.UITypeIds.UICommonBuyItemDialog then
                table.insert(t, dialog.Argument)
            end
        end
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIActivityEntryWelfareDialog}, t, isStack)
        return
    elseif moduleId == Constants.UITypeIds.UICompositeEntryDialog then
        ---材料合成
        if isNull(extraPara) and goodsVo then
            extraPara = { gainId = goodsVo.id, num = 1 }
        elseif not isNull(extraPara) then
            extraPara = checkTable(extraPara)
            if extraPara.gainId then
                extraPara = { gainId = extraPara.gainId, num = 1 }
            else
                extraPara = { gainId = extraPara[1], num = 1 }
            end
        end
    elseif moduleId == Constants.UITypeIds.UIWelfareMainDialog then
        local t = {}
        local dialogs = UIModule.CurrentScreen.dialogs
        for _, dialog in pairs(dialogs) do
            if checkNumber(dialog.Argument.id) ~= Constants.UITypeIds.UICommonBuyItemDialog then
                table.insert(t, dialog.Argument)
            end
        end
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIWelfareMainDialog, parameters = { selectedIndex = checkNumber(parameter) }, t, isStack })
        return
    elseif moduleId == Constants.UITypeIds.SalaryPlanDialog then
        UIModule.OpenDialog({ id = Constants.UITypeIds.SalaryPlanDialog })
        return
    elseif moduleId == Constants.UITypeIds.UIActionSecondMapDialog then
        local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
        local vo = ActionUtils.GetRegionSecondaryMapVo(parameter)
        local isUnlock, err = ActionUtils.IsUnlockRegionalSecondPoint(vo.id)
        if not isUnlock then
            GameUtils.Toast(err)
            return
        end
    elseif moduleId == Constants.UITypeIds.UIMaidCoffeeCookingMainDialog then
        local t = {}
        local dialogs = UIModule.CurrentScreen.dialogs
        for _, dialog in pairs(dialogs) do
            if checkNumber(dialog.Argument.id) ~= Constants.UITypeIds.UICommonBuyItemDialog then
                table.insert(t, dialog.Argument)
            end
        end
        UIModule.OpenDialog({ id = moduleId, parameters = { tableIndex = checkInt(row:Get("parameter")), id = not isNull(extraPara) and extraPara[1] or nil, cb = function()
        end } }, t, isStack)
        return
    end

    ---读取程序的模块配置表
    ---@type TableML.TableFileRow
    local prefabRow = UIModule.GetPrefabVoByRefId(moduleId)
    local status = checkInt(prefabRow:Get("status"))
    local attachParams = KCookie.Get(Constants.UICacheDataKeys.UIJumpExAttachParams)
    --非全屏界面
    if status == Constants.PrefabType.PartDialog then
        UIModule.OpenDialog({ id = moduleId, parameters = { type = parameter, goodsId = checkInt(goodsVo.refId), attachParams = attachParams } })
    elseif moduleId == Constants.UITypeIds.UICompositeEntryDialog then
        UIModule.OpenDialog({ id = moduleId, parameters = { area = checkNumber(parameter) } }, nil, isStack)
    elseif moduleId == Constants.UITypeIds.UIMaidCoffeeTakeoutDialog then
        local topDialog = UIModule.CurrentScreen:LastDialog()
        local parameters = {}
        if isSet(extraPara, "gainId") then
            ---不是一个列表
        else
            local area = checkNumber(table.takeFirst(extraPara))
            if area == 0 then
                area = 1
            end
            parameters = { area = area }
        end

        UIModule.OpenDialog({ id = moduleId, parameters = parameters }, { { id = topDialog.Argument.id } }, isStack)
    elseif moduleId == Constants.UITypeIds.UIActionEquipCollectionDialog then
        local t = {}
        local dialogs = UIModule.CurrentScreen.dialogs
        for _, dialog in pairs(dialogs) do
            table.insert(t, dialog.Argument)
        end
        UIModule.OpenDialog({ id = moduleId, parameters = extraPara }, t, isStack)
    elseif  moduleId == Constants.UITypeIds.ActivityGachaponSkinDialog then
        local t = {}
        local dialogs = UIModule.CurrentScreen.dialogs
        for _, dialog in pairs(dialogs) do
                table.insert(t, dialog.Argument)
        end
        ---@type ActivityCardSkinComponent
        local ActivityCardSkinComponent =  GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityCardSkinComponent)
        local index =  ActivityCardSkinComponent:GetIndexByActivityId(extraPara)
        KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_GACHAPON_SKIN_INDEX,index)
        UIModule.OpenDialog({ id = moduleId},  t, isStack)
    elseif checkInt(moduleId) == Constants.UITypeIds.LimitedTimeContinuousGiftDialog then
        ---@type ActivityMgr
        local ActivityMgr = import('Game.Activity.ActivityMgr'):GetInstance()
        local data = ActivityMgr:GetPayTimeChestData()
        if data and checkInt(data.endTime) > 0 then
            local playerId = GameUtils.GetPlayerId()
            CfUtils.WriteLocalData("OpenLimitedTimeContinuousGift_" .. playerId .. data.activityUuid, 1)
            CfUtils.DialogOpen(Constants.UITypeIds.LimitedTimeContinuousGiftDialog, nil, { UIArgs(Constants.UITypeIds.UIHomeView) })
        else
            GameUtils.Toast(localize("活动已结束"))
        end
    elseif self:IsNotShowBlackModule(moduleId) then
        UIModule.OpenDialog({ id = moduleId,parameters = {isShow = false} })
        -- 永久签到跳转    
    elseif checkInt(jumpID)  == 309 then
        ---@type PlayerComponent
        local PlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local isPop = PlayerComponent:IsPopPlayerEntryWelfare()
        if isPop then
            GameUtils.Toast(localize("功能暂未解锁"))
            return
        end
        local dayId = CfUtils.GetLocalData("Start_Contact_Sign", 0)
        local currentDayId = os.date("%Y%m%d", PlayerComponent:GetPlayerDojo():GetServerTime())
        local storeKey = string.format('%s_', Constants.UICacheDataKeys.UINoticeOpened)
        local storeKeyHour = string.format('%s_', Constants.UICacheDataKeys.UINoticeOpenedHour)
        local dateString = CfUtils.GetLocalData(storeKey, "")
        local hourString = CfUtils.GetLocalData(storeKeyHour, "")
        local curDateStr = os.date('%Y-%m-%d')
        local curHourStr = os.date('%H')
        local t = {}
        local dialogs = UIModule.CurrentScreen.dialogs
        for _, dialog in pairs(dialogs) do
                table.insert(t, dialog.Argument)
        end
        CfUtils.WriteLocalData("Start_Contact_Sign", currentDayId)
        CfUtils.WriteLocalData(storeKey, curDateStr)
        CfUtils.WriteLocalData(storeKeyHour, curHourStr)
        ---暂时注释掉，因为还有报错
        --self:GoToActivityPage(ActivityConstants.ActivityType.DailySin)
        local WelfareConstants = import("Game.UI.Welfare.WelfareConstants")
        UIModule.OpenDialog({ id = moduleId, parameters = { selectedIndex = WelfareConstants.OpenIds.DailySin } }, t, isStack)
       
    else
        
        ---跳转的其他的逻辑
        ---@type Engine.UI.UIRaycastBlocker
        local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
        blocker:AddCondition("JumpBlocker")
        cs_coroutine.start(function()
            if jumpType ~= Constants.JumpType.MaidCoffee 
            and moduleId ~= Constants.UITypeIds.UIOverseaTowerEntryDialog 
            and moduleId ~= Constants.UITypeIds.ActionPointMapBossDialog
            and moduleId ~= Constants.UITypeIds.OverseaStore
            then
                Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
            end
            ---@type Engine.UI.UILuaDialog
            local topDialog = UIModule.CurrentScreen:LastDialog()
            ---要跳转的id与当前模块是同一id, 直接刷新界面的
            if topDialog and topDialog.Argument.id == moduleId then
                if topDialog.Env and not isNull(topDialog.Env.FreshUI) then
                    topDialog.Env:FreshUI(checkInt(checkInt(goodsVo.refId)), parameter)
                else
                    GameUtils.Toast(localize("已在当前页面"))
                end
            else
                local isShow = false
                local time = 0

                local showBlack = true
                if moduleId == Constants.UITypeIds.ConvertExchangeDialog then
                    local dialogs = UIModule.CurrentScreen.dialogs
                    for _, v in pairs(dialogs) do
                        if v.Argument.id == Constants.UITypeIds.ConvertExchangeDialog then
                            if v.Env and not isNull(v.Env.FreshUI) then
                                v.Env:FreshUI(checkInt(goodsVo.refId), parameter)
                            end
                            blocker:RemoveCondition("JumpBlocker")
                            return 
                        end
                    end
                end
                if moduleId == Constants.UITypeIds.UIOverseaTowerEntryDialog 
                or moduleId == Constants.UITypeIds.ActionPointMapBossDialog
                or self:IsNotShowBlackModule(moduleId) then
                    showBlack = false
                end
                if showBlack then
                    GameUtils.ShowBlackOverlay(nil, function()
                        while not isShow do
                            coroutine.yield(Yielders.EndOfFrame)
                        end
                        --coroutine.yield(WaitForSeconds(0.6))
                    end)
                    coroutine.yield(WaitForSeconds(time))
                end

                local t = {}
                local dialogs = UIModule.CurrentScreen.dialogs
                for _, dialog in pairs(dialogs) do
                    --if checkNumber(dialog.Argument.id) ~= Constants.UITypeIds.UIFightTeamCardChoose and checkNumber(dialog.Argument.id) ~= 3720 then
                    if checkNumber(dialog.Argument.id) ~= Constants.UITypeIds.UICommonBuyItemDialog then
                        table.insert(t, dialog.Argument)
                    end
                    --end
                end

                local screenId = UIModule.CurrentScreen.Argument.id
                if screenId == Constants.UITypeIds.UIMaidCoffeeEnterScene and jumpType ~= Constants.JumpType.MaidCoffee then
                    xTry(function()
                        CS.UnityEngine.Application.backgroundLoadingPriority = CS.UnityEngine.ThreadPriority.High
                        CS.UINavigationBarRoot.Instance:SetActive(false)
                        ---关闭所有的窗口
                        xTry(function()
                            local needWaitDialogClose = false
                            local coWait = CS.Engine.Lib.CoWait.Start()
                            local support = require('Frame.support')
                            for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
                                local isRemove = string.isEmpty(v.Argument.extra)
                                local coClose = UIModule.CloseDialog(v, isRemove)
                                if not isNull(coClose) then
                                    needWaitDialogClose = true
                                    coWait:Coroutine(coClose)
                                end
                            end
                            UIModule.CurrentScreen.dialogs:Clear()
                            while needWaitDialogClose and not coWait.IsFinish do
                                coroutine.yield()
                            end
                            CS.Engine.UI.UIModule.ResetStack()
                            cs_coroutine.yield_return(UIModule.OpenScreen(UIArgs(Constants.UITypeIds.UISceneHome), true, nil))
                            ---@type XMainHome
                            local env = UIModule.CurrentScreen.Env
                            cs_coroutine.yield_return(env:AsyncLoadingResources())
                            Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
                            UIModule.CurrentScreen.isLoadingFinished = true
                            CS.UnityEngine.Application.backgroundLoadingPriority = CS.UnityEngine.ThreadPriority.Normal
                        end)
                    end, function()

                    end)

                elseif screenId == Constants.UITypeIds.BattleScene then
                    UIModule.CurrentScreen.Argument = checkTable({ id = Constants.UITypeIds.UISceneHome, hasExcluded = false })

                    FightPreWarMgr:GetInstance():ClearBattleBuff()
                    if BattleViewMgr then
                        BattleViewMgr:SetCameraVMActive(false)
                        BattleViewMgr:ResetOutsetBattleSettings()
                    end
                    if BattleEndMgr then
                        --- 结算表演的timeline会改镜头焦距，需要在打开主场景之前先重置掉才行
                        BattleEndMgr:ResetCameraAndLight()
                    end

                    local coWait = CoWait.Start()
                    local count = UIModule.CurrentScreen.dialogs.Count
                    xTry(function()
                        for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
                            if not isNull(v) then
                                local co = UIModule.CloseDialog(v, true)
                                if not isNull(co) then
                                    coWait:Coroutine(co)
                                end
                            end
                        end
                        UIModule.CurrentScreen.dialogs:Clear()
                    end)
                    while not coWait.IsFinish and count > 0 do
                        coroutine.yield()
                    end

                    Events.Broadcast(Constants.EventNames.FightEndPreHandle)
                    cs_coroutine.yield_return()
                    local arguments = UIModule.PopPage()
                    if not isNull(arguments) and arguments.Count > 0 then
                        xpcall(function()
                            for i, v in support.list_ipairs(arguments) do
                                cs_coroutine.yield_return(UIModule.OpenDialog(v.id, v))
                            end
                        end, function()
                            printError("[OpenLoadingPanel] OpenDialog Error")
                            cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIHomeView }))
                        end)
                    else
                        ---初始需要打包主界面
                        cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIHomeView }))
                    end

                    xpcall(function()

                        UINavigationBarRoot.Instance:SetActive(true)
                        if BattleViewMgr then
                            BattleViewMgr:OnDestroy()
                            BattleViewMgr = nil
                        end
                        CS.UnityEngine.LightmapSettings.lightProbes = nil
                    end, function(err)
                        local nativeFXMgr = CS.Game.Native.ParticleManager.Instance
                        nativeFXMgr:TearDown()
                        printError(tostring(err))
                    end)

                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.6))
                    CriWareUtils.PlayRandomBGMFromCDList()

                    t = {}
                    local dialogs = UIModule.CurrentScreen.dialogs
                    for _, dialog in pairs(dialogs) do
                        --if checkNumber(dialog.Argument.id) ~= Constants.UITypeIds.UIFightTeamCardChoose and checkNumber(dialog.Argument.id) ~= 3720 then
                        table.insert(t, dialog.Argument)
                        --end
                    end
                else
                    local FishingMgr = import('Game.UI.Fishing.FishingMgr')
                    local id = FishingMgr:GetInstance()._curFishPlaceId
                    --渔场的
                    if checkNumber(id) > 0 then
                        xTry(function()
                            --GameUtils.CommonShowBlackAnimation()
                            CS.UINavigationBarRoot.Instance:SetActive(false)
                            ---关闭所有的窗口
                            xTry(function()
                                local needWaitDialogClose = false
                                local coWait = CS.Engine.Lib.CoWait.Start()
                                local support = require('Frame.support')
                                for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
                                    local isRemove = string.isEmpty(v.Argument.extra)
                                    local coClose = UIModule.CloseDialog(v, isRemove)
                                    if not isNull(coClose) then
                                        needWaitDialogClose = true
                                        coWait:Coroutine(coClose)
                                    end
                                end
                                UIModule.CurrentScreen.dialogs:Clear()
                                while needWaitDialogClose and not coWait.IsFinish do
                                    coroutine.yield()
                                end
                                cs_coroutine.yield_return(FishingMgr:GetInstance():Clear())
                                CS.Engine.UI.UIModule.ResetStack()
                                KCookie.Set(Constants.UICacheDataKeys.OVERSEA_MANAGER_SCENE_STATE, 1)
                                cs_coroutine.yield_return(UIModule.OpenScreen(UIArgs(Constants.UITypeIds.UISceneHome), true, nil))
                                ---@type XMainHome
                                local env = UIModule.CurrentScreen.Env
                                cs_coroutine.yield_return(env:AsyncLoadingResources())
                                Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
                                UIModule.CurrentScreen.isLoadingFinished = true
                                CS.UnityEngine.Application.backgroundLoadingPriority = CS.UnityEngine.ThreadPriority.Normal
                            end)
                        end, function()

                        end)
                    end

                end
                
                if moduleId == Constants.UITypeIds.GachaponEntry then
                    CfUtils.ResetNavigatorCustomBackAction()
                    local gachaponUtils = import('Game.Gachapon.GachaponUtils')
                    local data = {}
                    -- 先读表的跳转定义
                    if checkInt(parameter) > 0 then
                        data.jumpPool = checkInt(parameter)
                    end
                    -- 如果有自定义的，啧覆盖表的设置
                    if checkInt(extraPara) > 0 then
                        data.jumpPool = checkInt(extraPara)
                    end
                    coroutine.yield(gachaponUtils.OpenGachapon(data, t, isStack, function()
                        KCookie.Set(Constants.UICacheDataKeys.StartJump, 1)
                        GameUtils.CommonShowBlackAnimation()
                    end, function()
                        isShow = true
                    end))
                    Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = false })
                elseif jumpType == Constants.JumpType.MaidCoffee then
                    local autoData = { row = row, id = not isNull(extraPara) and extraPara[1] or nil }
                    KCookie.Set("CafeIsAutoOpen", 1)
                    cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeManagerDialog, parameters = { autoData = autoData } }, t, isStack))
                    blocker:RemoveCondition("JumpBlocker")
                elseif moduleId == Constants.UITypeIds.StoreEntry or moduleId == Constants.UITypeIds.StoreChargeDialog then
                    CfUtils.ResetNavigatorCustomBackAction()
                    local storeUtils = import("Game.UI.Store.StoreUtils")
                    storeUtils.OpenStore(parameter, t, nil, checkBool(isHomeJump))
                elseif moduleId == Constants.UITypeIds.StoreItem then
                    CfUtils.ResetNavigatorCustomBackAction()
                    local storeUtils = import("Game.UI.Store.StoreUtils")
                    storeUtils.OpenVarietyStore(parameter, t, nil, checkBool(isHomeJump))
                    --迷宫单独处理
                elseif moduleId == Constants.UITypeIds.PatrolEntryDialog then
                    KCookie.Set(Constants.UICacheDataKeys.JumpLastModuleId, topDialog.Argument.id)
                    local MazeMgr = import('Game.Maze.MazeMgr')
                    MazeMgr:GetInstance():EnterMaze(t)
                    --世界boss
                elseif moduleId == Constants.UITypeIds.WorldBossEntry then
                    CfUtils.ResetNavigatorCustomBackAction()
                    local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
                    --worldBossComponent:OnWorldBossEnter()
                    cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIWorldBossMainDialog }, t, isStack))

                    --[[
                    local isOpen = worldBossComponent:IsOpen()
                    if isOpen then
                        worldBossComponent:WorldBossHomeReq(
                                function()
                                    cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIWorldBossMainDialog }, t, isStack))
                                end
                        )
                    else
                        cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIWorldBossMainDialog }, t, isStack))
                    end
                    ]]
                elseif moduleId == Constants.UITypeIds.UIActivityMainDialog then
                    local type = checkNumber(parameter)
                    if type == ActivityConstants.ActivityType.CakeShop then
                        local ActivityMgr = import('Game.Activity.ActivityMgr')
                        local activityMgr = ActivityMgr:GetInstance()
                        ---@type ActivityConstants
                        local ActivityConstants = import("Game.Activity.ActivityConstants")
                        local activityId = activityMgr:GetActivityIdByActivityType(ActivityConstants.ActivityType.CakeShop)
                        if activityId then
                            local activityDojo = activityMgr:GetActivityComponent():GetDojoByActivityId(activityId)
                            if isNull(activityDojo) then
                                return
                            end
                            local vo = checkTable(activityDojo.unlock)[1]
                            local isUnlock = false
                            if vo then
                                isUnlock = GameUtils.IsUnlockedSingle(vo.targetType, vo.targetNum, vo.targetId)
                            else
                                isUnlock = true
                            end
                            
                            if not isUnlock then
                                local vo = activityDojo.unlock[1]
                                local err = GameUtils.GetUnlockDescr(vo.targetType, vo.targetNum, vo.targetId)
                                GameUtils.Toast(err)
                                return
                            end
                            UIModule.OpenDialog({ id = activityDojo.moduleId, parameters = { activityData = activityDojo}}, t, isStack)
                        end
                    else
                        ---@type ActivityUtils
                        local activityUtils = import("Game.Activity.ActivityUtils")
                        activityUtils.OpenActivityView(checkInt(extraPara), t)
                    end
                   
                elseif moduleId == Constants.UITypeIds.UINightCatITowerDialog then
                    local ActivityMgr = import('Game.Activity.ActivityMgr')
                    local activityMgr = ActivityMgr:GetInstance()
                    local activityId = activityMgr:GetActivityIdByActivityType(ActivityConstants.ActivityType.NightCat)
                    if activityId then
                        UIModule.OpenDialog({ id = Constants.UITypeIds.ActivityNightCatDialog, parameters = { activityId = activityId, openTower = true } },
                                { { id = Constants.UITypeIds.UIActivityMainDialog } })
                    end
                elseif moduleId == Constants.UITypeIds.ActivityDreamAdventuresMain then
                    local ActivityMgr = import('Game.Activity.ActivityMgr')
                    local activityMgr = ActivityMgr:GetInstance()
                    ---@type ActivityConstants
                    local ActivityConstants = import("Game.Activity.ActivityConstants")
                    local activityId = activityMgr:GetActivityIdByActivityType(ActivityConstants.ActivityType.ConstractFood)
                    if activityId then
                        local activityDojo = activityMgr:GetActivityComponent():GetDojoByActivityId(activityId)
                        if isNull(activityDojo) then
                            return
                        end
                        
                        local vo = checkTable(activityDojo.unlock)[1]
                        local isUnlock = false
                        if vo then
                            isUnlock = GameUtils.IsUnlockedSingle(vo.targetType, vo.targetNum, vo.targetId)
                        else
                            isUnlock = true
                        end
                        
                        if not isUnlock then
                            local vo = activityDojo.unlock[1]
                            local err = GameUtils.GetUnlockDescr(vo.targetType, vo.targetNum, vo.targetId)
                            GameUtils.Toast(err)
                            return
                        end
                        local DreamAdvUtils = import('Game.Activity.DreamAdventures.DreamAdventuresUtils')
                        xRecord.record('6-005', string.format('enter_activity_page_%d', checkInt(activityDojo.id)))
                        DreamAdvUtils.EnterDreamAdventures(t, {activityDojo = activityDojo, random = true})
                    end
                elseif moduleId == Constants.UITypeIds.UIHomeGatherActivityDialog then
                    -- 这里moudleId 指定  Constants.UITypeIds.UIHomeGatherActivityDialog
                    GameUtils.AddGatherActvity()
                elseif moduleId == Constants.UITypeIds.GroceryDialog then
                    local groceryUtils = import('Game.Grocery.GroceryUtils')
                    local findId = checkTable(goodsVo).id
                    if parameter ~= "" then
                        findId = nil
                    end
                    groceryUtils.OpenGroceryStore(parameter, t, { findId = findId }, checkBool(isHomeJump))
                elseif moduleId == Constants.UITypeIds.OverseaStore then
                    local storeUtils = import('Game.OverseaStore.OverseaStoreUtils')
                    local findId = checkTable(goodsVo).id
                    if parameter ~= "" then
                        findId = nil
                    end
                    storeUtils.OpenStore(parameter, t, { findId = findId }, checkBool(isHomeJump))
                elseif moduleId == Constants.UITypeIds.UIOverseaTowerEntryDialog then
                    parameter = checkInt(parameter)
                    if parameter == 0 then
                        -- 爬塔入口
                        cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIOverseaTowerEntryDialog }, t, isStack))
                        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
                        blocker:RemoveCondition("JumpBlocker")
                    elseif parameter == 100 then
                        -- 收菜界面
                        cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIOverseaTowerEntryDialog, parameters = { jumpTargetId = parameter } }, t, isStack))
                        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
                        -- 跳转完成以后
                    else
                        -- 塔
                        local towerQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
                        if towerQuestComponent:HasClimbTowerInfo() then
                            cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIOverseaTowerInsideDialog, parameters = { type = parameter } }, t, isStack))
                            Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
                            blocker:RemoveCondition("JumpBlocker")
                        else
                            local isFinish = false
                            towerQuestComponent:OverseaClimbingTowerHomeReq(function()
                                isFinish = true
                            end)
                            while not isFinish do
                                cs_coroutine.yield_return()
                            end
                            cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIOverseaTowerInsideDialog, parameters = { type = parameter } }, t, isStack))
                            blocker:RemoveCondition("JumpBlocker")
                            Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
                        end
                    end
                    return
                elseif moduleId == Constants.UITypeIds.LadderStruggleMainDialog
                        or moduleId == Constants.UITypeIds.LadderStruggleSingleMainDialog then
                    parameter = checkInt(parameter)
                    cs_coroutine.yield_return(UIModule.OpenDialog({ id = moduleId, parameters = { systemName = parameter } }, t, isStack))
                elseif moduleId == Constants.UITypeIds.ActionPointMapBossDialog then
                    parameter = checkInt(parameter)
                    parameter = parameter == 0 and 1 or parameter
                    cs_coroutine.yield_return(UIModule.OpenDialog({ id = moduleId, parameters = { bossTypeId = parameter } }, t, isStack))
                    Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
                elseif moduleId == Constants.UITypeIds.OverseaClubBossMainDialog then
                    self.isCultivate = true
                    if ClubUtils.GetClubComp():IsJoinClub() then
                        CfUtils.DialogOpen(Constants.UITypeIds.OverseaClubBossMainDialog, nil, t,isStack)
                    else
                        CfUtils.DialogOpen(Constants.UITypeIds.UIOverseaClubListDialog, nil, t,isStack)
                    end
                elseif moduleId == Constants.UITypeIds.UIActionFairylandStageSelectDialog then
                    local FairylandComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FairylandComponent)
                    FairylandComponent:FairylandHome(function ()
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UIActionFairylandStageSelectDialog, parameters = {} }, t, isStack)
                    end)
                else
                    local isOpen, parTable, errStr = self:GetTypeJumpParameter(moduleId, parameter, goodsVo, position, extraPara)
                    --[[
                    --装备副本需要转一层
                    if moduleId == Constants.UITypeIds.UIFastReliefDisasterResponseDialog then
                        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.EquipQuestComponent)
                        --有挑战关卡
                        if checkNumber(comp:GetCurSeniorQuestId()) ~= 0 then
                            moduleId = Constants.UITypeIds.UIFastReliefDisasterResponseMapDialog
                        end
                    end
                    ]]
                    --主线硬转一层  未解锁得章节改为章节选择入口
                    --[[
                    if moduleId == Constants.UITypeIds.UIMainChapterDialog then
                        local curChapterId = QuestConfMgr:GetInstance():GetCurChapterId()
                        local isUnlock = QuestConfMgr:GetInstance():IsUnlockChapter(curChapterId)
                        if isUnlock then
                            parTable = { chapterId = curChapterId }
                        else
                            moduleId = Constants.UITypeIds.UIMainBattlePanelDialog
                        end
                    end
                    ]]
                    if moduleId == Constants.UITypeIds.UIMainChapterDialog then
                        local chapterId = 0
                        if checkNumber(parameter) == Constants.IDType.QuestMain then
                            chapterId = QuestConfMgr:GetInstance():GetCurChapterId()
                        elseif checkNumber(parameter) == Constants.IDType.QuestMainChallenge then
                            chapterId = QuestConfMgr:GetInstance():GetCurChallengeChapterId()
                        end
                        local isOpen = ThirdDownloadManager:IsMainOpenDownloadThirdPackage()
                        if isOpen then
                            CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.ThirdPackageDownloadDialog} )
                            return
                        end
                    end
                    if isOpen then
                        CfUtils.ResetNavigatorCustomBackAction()
                        KCookie.Set(Constants.UICacheDataKeys.StartJump, 1)

                        if goodsVo then
                            parTable.goodsId = checkInt(goodsVo.refId)
                        end
                        parTable.attachParams = attachParams

                        if extraPara then
                            extraPara = checkTable(extraPara)
                            for k, v in pairs(extraPara) do
                                parTable[k] = v
                            end
                        end

                        --GameUtils.CommonShowBlackAnimation()
                        cs_coroutine.yield_return(UIModule.OpenDialog({ id = moduleId, parameters = parTable }, t, isStack))
                        isShow = true

                        if checkNumber(KCookie.Get("IsUIActionEquipCollectionDialogJump")) == 1 then
                            UIModule.RemoveDialogRecord(Constants.UITypeIds.UIActionEquipCollectionDialog)
                            KCookie.Set("IsUIActionEquipCollectionDialogJump", 0)
                        end
                    else
                        GameUtils.Toast(errStr)
                        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
                    end
                end
                isShow = true
            end
            blocker:RemoveCondition("JumpBlocker")
        end)
    end
end

---根据具体类型，跳转
function GoodsConfMgr:GetTypeJumpParameter(moduleId, parameter, goodsVo, position, extraPara)
    extraPara = checkTable(extraPara)
    local Parameter = {}
    local isCanJump = true  -- 是否可以跳
    local errStr = ""

    --参数
    local goodArg
    --如果有物品 以物品的为主
    if goodsVo and table.count(goodsVo) > 0 then
        goodsVo = checkTable(goodsVo)
        if isSet(goodsVo, "jumpParameter") then
            local t = checkTable(goodsVo.jumpParameter)
            goodArg = t[checkNumber(position)]
        end
    else
        goodArg = parameter
    end

    if moduleId == Constants.UITypeIds.CultivateMain then
        ---@type CardProgressionUtils
        local CardProgressionUtils = import("Game.CardProgression.CardProgressionUtils")
        Parameter, errStr = CardProgressionUtils.CheckJumpCultivateMain(parameter, extraPara)
        isCanJump = Parameter ~= nil
    elseif moduleId == Constants.UITypeIds.CardProgressionIntroduction then
        ---@type CardProgressionUtils
        local CardProgressionUtils = import("Game.CardProgression.CardProgressionUtils")
        Parameter, errStr = CardProgressionUtils.CheckJumpFavor(parameter, extraPara)
        isCanJump = Parameter ~= nil
        --主线地图 /goodArg:
    elseif moduleId == Constants.UITypeIds.UIMainChapterDialog then
        --[[
        local targetQuestId = checkNumber(extraPara[1])
        if targetQuestId <= 0 then
            isCanJump = true
            --errStr = localize("主线跳转没有配置关卡id")
        else
            local vo = QuestConfMgr:GetInstance():GetQuestVoById(targetQuestId)
            if not vo then
                isCanJump = false
                errStr = localize("主线跳转没有配置关卡id")
            else
                local type = GoodsUtils.GetIdType(targetQuestId, Constants.IDArea.Quests)
                local isUnlock = QuestConfMgr:GetInstance():IsUnlockChapter(vo.chapter)
                --解锁了才进去
                if isUnlock then
                    Parameter = { chapterId = vo.chapter, type = type }
                    --未解锁进主线选择界面
                else
                    moduleId = Constants.UITypeIds.UIMainBattlePanelDialog
                end
            end
        end
        ]]

        local chapterId = 0
        if checkNumber(parameter) == Constants.IDType.QuestMain then
            chapterId = QuestConfMgr:GetInstance():GetCurChapterId()
        elseif checkNumber(parameter) == Constants.IDType.QuestMainChallenge then
            chapterId = QuestConfMgr:GetInstance():GetCurChallengeChapterId()
        end
        if checkNumber(parameter) == Constants.IDType.QuestMainChallenge then
            if not QuestConfMgr:GetInstance():IsUnlockChallengeChapter(chapterId) then
                isCanJump = false
                errStr = localize("未解锁章节")
            else
                Parameter = { chapterId = chapterId, type = parameter }
                Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
            end
        else
            if not QuestConfMgr:GetInstance():IsUnlockChapter(chapterId) then
                isCanJump = false
                errStr = localize("未解锁章节")
            else
                Parameter = { chapterId = chapterId, type = parameter }
                Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
            end
        end
        --主线选章节的
    elseif moduleId == Constants.UITypeIds.UIMainBattlePanelDialog then
        --主线
        if checkNumber(parameter) == Constants.IDType.QuestMain or checkNumber(parameter) == Constants.IDType.QuestMainChallenge then
            local chapterId = 0
            if checkNumber(parameter) == Constants.IDType.QuestMain then
                chapterId = QuestConfMgr:GetInstance():GetCurChapterId()
            elseif checkNumber(parameter) == Constants.IDType.QuestMainChallenge then
                chapterId = QuestConfMgr:GetInstance():GetCurChallengeChapterId()
            end

            KCookie.Set("MainQuestType", parameter)
            Parameter = { index = 1, type = parameter }
            --角色故事
        else
            Parameter = { index = 2 }
        end

        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
    elseif moduleId == Constants.UITypeIds.ActionEntryDialog then
        ---日常副本地图 /goodArg:标签id
        Parameter = { type = parameter }
        --战前副本入口 /goodArg:标签id
    elseif moduleId == Constants.UITypeIds.BattleSelection then
        Parameter = { curTab = checkNumber(parameter) }
        --编队跳转 /goodArg:关卡id
    elseif moduleId == Constants.UITypeIds.UIFightTeamChoose then
        local questType = GoodsUtils.GetIdType(goodArg, Constants.IDArea.Quests)
        --主线不能多次重复刷  判断一下有没有通关
        if questType == Constants.IDType.QuestMain then
            --已解锁且没通关过
            isCanJump = ((not QuestConfMgr:GetInstance():IsPassQuest(goodArg)) and QuestConfMgr:GetInstance():IsUnlockQuest(goodArg))
        elseif questType == Constants.IDType.QuestDaily or questType == Constants.IDType.QuestCoinsCopy or questType == Constants.IDType.QuestExpCopy or questType == Constants.IDType.QuestUpStarCopy then
            local vo = QuestConfMgr:GetInstance():GetQuestVoById(goodArg)
            if vo then
                --副本关卡类型
                vo = QuestConfMgr:GetInstance():GetDailyQuestTypeVoByType(vo.type)
            end
            if vo then
                local isUnlock = GameUtils.IsUnlocked(checkString(vo.unlockType), checkString(vo.unlockNum))
                if isUnlock then
                    local dailyQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
                    local isFinish = false
                    GameUtils.Request(Interfaces.DailyQuest, {}, function(request, response)
                        if checkInt(response.errCode) == 0 then
                            dailyQuestComponent:Initial(response.data)
                        end
                        isFinish = true
                    end)
                    local time = 0
                    --等一下数据的接收
                    while not isFinish do
                        coroutine.yield(Yielders.EndOfFrame)
                        time = time + 1
                        if time >= 300 then
                            isFinish = true
                            errStr = localize("初始化日常数据超时，请重新尝试")
                        end
                    end
                else
                    errStr = GameUtils.GetUnlockDescr(checkString(vo.unlockType), checkString(vo.unlockNum))
                    isCanJump = false
                end
            end

            if isCanJump then
                Parameter = { levelId = goodArg }
            end
        end
        --装备副本
    elseif moduleId == Constants.UITypeIds.UIFastReliefDisasterResponseDialog then
        Parameter = { curType = checkNumber(parameter) }
        --手机摇一摇
    elseif moduleId == Constants.UITypeIds.UIFeelingNaughtyDialog then
        if GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id224) then
            local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)
            local isFinish = false
            GameUtils.Request(Interfaces.PhoneHome, {}, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local jsonData = response.data
                    comp:Initial(jsonData.cats)
                end
                isFinish = true
            end)

            local time = 0
            --等一下数据的接收
            while not isFinish do
                coroutine.yield(Yielders.EndOfFrame)
                time = time + 1
                if time >= 300 then
                    isFinish = true
                    errStr = localize("初始化日常数据超时，请重新尝试")
                end
            end
        else
            isCanJump = false
            errStr = GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id18)
        end
        --手机购物
    elseif moduleId == Constants.UITypeIds.UIFeelingShopDialog then
        if GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id223) then
            local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)
            local isFinish = false
            GameUtils.Request(Interfaces.PhoneHome, {}, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local jsonData = response.data
                    comp:Initial(jsonData.cats)
                end
                isFinish = true
            end)

            local time = 0
            --等一下数据的接收
            while not isFinish do
                coroutine.yield(Yielders.EndOfFrame)
                time = time + 1
                if time >= 300 then
                    isFinish = true
                    errStr = localize("初始化日常数据超时，请重新尝试")
                end
            end
        else
            isCanJump = false
            errStr = GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id18)
        end
        --手机主界面
    elseif moduleId == Constants.UITypeIds.UIFeelingMainDialog then
        if GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id220) then
            local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)
            local isFinish = false
            GameUtils.Request(Interfaces.PhoneHome, {}, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    local jsonData = response.data
                    comp:Initial(jsonData.cats)
                end
                isFinish = true
            end)

            local time = 0
            --等一下数据的接收
            while not isFinish do
                coroutine.yield(Yielders.EndOfFrame)
                time = time + 1
                if time >= 300 then
                    isFinish = true
                    errStr = localize("初始化日常数据超时，请重新尝试")
                end
            end
        else
            isCanJump = false
            errStr = GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id220)
        end
    elseif moduleId == Constants.UITypeIds.UIActivityMainDialog then
        local isFinish = false
        GameUtils.Request(Interfaces.ActivityHome, {}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                local jsonData = response.data
                local ActivityUtils = import("Game.Activity.ActivityUtils")
                ActivityUtils.ConventSecondToTimeStamp(jsonData.activities)
                Parameter = { data = jsonData }
            end
            isFinish = true
        end)
        local time = 0
        --等一下数据的接收
        while not isFinish do
            coroutine.yield(Yielders.EndOfFrame)
            time = time + 1
            if time >= 300 then
                isFinish = true
                errStr = localize("初始化问卷数据超时，请重新尝试")
            end
        end
    elseif moduleId == Constants.UITypeIds.UIActionSecondMapDialog then
        local isFinish = false

        local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
        local vo = ActionUtils.GetRegionSecondaryMapVo(parameter)
        local isUnlock, err = ActionUtils.IsUnlockRegionalSecondPoint(vo.id)
        if isUnlock then
            local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
            comp:OverseaRegionalHomeReq(function()
                KCookie.Set("UIActionSecondMapDialogtargetPointId", parameter)

                --默认是外部参数
                local finQuestId = checkNumber(extraPara[1])
                --如果是道具跳转  直接道具参数覆盖
                if goodsVo and table.count(goodsVo) > 0 then
                    local par1 = checkNumber(goodArg)
                    --俩位数为类型 取这个类型的最新关卡id
                    if par1 < 100 then
                        finQuestId = ActionUtils.GetCurRegionQuestId(vo.id, par1)
                        --关卡id
                    else
                        local finQuestId = par1
                    end
                end

                Parameter = { id = vo.regionBelong, targetQuestId = finQuestId, goodsVo = goodsVo }
                isFinish = true
            end)
        else
            isCanJump = false
            errStr = err
            isFinish = true
        end

        local time = 0
        --等一下数据的接收
        while not isFinish do
            coroutine.yield(Yielders.EndOfFrame)
            time = time + 1
            if time >= 300 then
                isCanJump = false
                isFinish = true
                errStr = localize("初始化区域数据超时，请重新尝试")
            end
        end
    elseif moduleId == Constants.UITypeIds.UIActionPointMapDialog then
        local isFinish = false

        local t = checkTable(CfUtils.Split(parameter))
        local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
        local vo = ActionUtils.GetRegionSecondaryMapVo(t[1])
        local isUnlock, err = ActionUtils.IsUnlockRegionalSecondPoint(vo.id)
        if isUnlock then
            local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
            comp:OverseaRegionalHomeReq(function()
                --默认是外部参数
                local finQuestId = checkNumber(extraPara[1])
                --如果是道具跳转  直接道具参数覆盖
                if goodsVo and table.count(goodsVo) > 0 then
                    local par1 = checkNumber(goodArg)
                    if par1 > 0 then
                        --俩位数为类型 取这个类型的最新关卡id
                        if par1 < 1000 then
                            finQuestId = ActionUtils.GetCurRegionQuestId(vo.id, par1)
                            --关卡id
                        else
                            finQuestId = par1
                        end
                    end
                end

                if checkNumber(vo.type) == Constants.RegionSecondMapPointType.Sp then
                    local dailyQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
                    dailyQuestComponent:DailyQuestHomeReq(function()
                        Parameter = { id = vo.id, dailyType = checkNumber(t[2]), targetQuestId = finQuestId, goodsVo = goodsVo }
                        isFinish = true
                    end)
                else
                    Parameter = { id = vo.id, targetQuestId = finQuestId, goodsVo = goodsVo }
                    isFinish = true
                end
            end)
        else
            isCanJump = false
            errStr = err
            isFinish = true
        end

        local time = 0
        --等一下数据的接收
        while not isFinish do
            coroutine.yield(Yielders.EndOfFrame)
            time = time + 1
            if time >= 300 then
                isCanJump = false
                isFinish = true
                errStr = localize("初始化区域数据超时，请重新尝试")
            end
        end

    elseif moduleId == Constants.UITypeIds.UIActionBossCollectionDialog then
        local isFinish = false
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
        comp:OverseaRegionalHomeReq(function()
            isFinish = true
            Parameter = {}
        end)
        local time = 0
        --等一下数据的接收
        while not isFinish do
            coroutine.yield(Yielders.EndOfFrame)
            time = time + 1
            if time >= 300 then
                isFinish = true
                isCanJump = false
                errStr = localize("初始化区域数据超时，请重新尝试")
            end
        end
    elseif moduleId == Constants.UITypeIds.UIActionCityStoreDialog then
        local isFinish = false

        local ind = checkNumber(extraPara[1])
        if goodsVo and table.count(goodsVo) > 0 then
            ind = checkNumber(goodArg)
        end

        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
        comp:OverseaRegionalHomeReq(function()
            local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
            local isUnlock, err = ActionUtils.IsUnlockStore(parameter)

            isCanJump = isUnlock
            errStr = err
            Parameter = { storeId = parameter, labInd = ind }

            isFinish = true
        end)

        local time = 0
        --等一下数据的接收
        while not isFinish do
            coroutine.yield(Yielders.EndOfFrame)
            time = time + 1
            if time >= 300 then
                isFinish = true
                isCanJump = false
                errStr = localize("初始化区域数据超时，请重新尝试")
            end
        end
    elseif moduleId == Constants.UITypeIds.UIActionConstructDialog then
        local isFinish = false
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
        comp:OverseaRegionalHomeReq(function()
            local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
            local isUnlock, err = ActionUtils.IsUnlockRegionalPoint(parameter)

            isCanJump = isUnlock
            errStr = err
            Parameter = { mapId = parameter }

            isFinish = true
        end)

        local time = 0
        --等一下数据的接收
        while not isFinish do
            coroutine.yield(Yielders.EndOfFrame)
            time = time + 1
            if time >= 300 then
                isFinish = true
                isCanJump = false
                errStr = localize("初始化区域数据超时，请重新尝试")
            end
        end
    elseif moduleId == Constants.UITypeIds.ConvertExchangeDialog then
        Parameter = {index = parameter}
    end

    return isCanJump, Parameter, errStr
end

return GoodsConfMgr